## Why This Is Asked

This question evaluates your ability to design end-to-end tests for complex, privacy-conscious configurations spanning multiple services, data residency requirements, and dynamic rollout strategies.

## Key Concepts
- Feature-flag propagation across 120 microservices via event bus
- Canary vs. percentage-based rollouts and race condition handling
- Per-tenant caches with data residency enforcement
- Cache invalidation and immutable audit logging
- Fault injection: service outages, retry logic, and exponential backoff

## Code Example
```javascript
// Pseudo-test skeleton (using your preferred E2E framework)
async function testFlagRollout() {
  const tenants = await seedTenants([
    { id: 'tenant-1', region: 'us-east' },
    { id: 'tenant-2', region: 'eu-west' },
    { id: 'tenant-3', region: 'ap-south' }
  ]);

  // Test canary rollout (5%)
  await flagService.update({ key: 'new-feature', rollout: 5 });
  await waitForPropagation(60000);

  // Verify canary distribution
  for (const tenant of tenants) {
    const flag = await getFlag(tenant.id, 'new-feature');
    expect(flag.enabled).toBe(tenant.region === 'us-east');
    await verifyAuditLog(tenant.id, 'new-feature', 'canary');
  }

  // Test 50% rollout
  await flagService.update({ key: 'new-feature', rollout: 50 });
  await waitForPropagation(60000);

  // Verify all services observe flag
  const serviceFlags = await collectFromAllServices('new-feature');
  expect(serviceFlags.every(f => f.enabled)).toBe(true);

  // Verify cache invalidation
  for (const tenant of tenants) {
    const cacheStatus = await getCacheStatus(tenant.id);
    expect(cacheStatus.invalidated).toBe(true);
  }
}

// Fault injection: service outage
async function testFlagServiceOutage() {
  await simulateServiceOutage('flag-service');
  await flagService.update({ key: 'fallback-test', rollout: 100 });

  // Verify retries and eventual consistency
  await waitForPropagation(120000);
  const flags = await collectFromAllServices('fallback-test');
  expect(flags.every(f => f.enabled)).toBe(true);
}

// Load test: rapid toggles and race conditions
async function testRapidToggles() {
  const toggles = Array(100).fill().map((_, i) => ({
    key: `feature-${i}`,
    rollout: Math.random() * 100
  }));

  await Promise.all(toggles.map(t => flagService.update(t)));
  await waitForPropagation(60000);

  // Verify consistency under load
  for (const toggle of toggles) {
    const flags = await collectFromAllServices(toggle.key);
    const enabledCount = flags.filter(f => f.enabled).length;
    const expectedCount = Math.floor(120 * (toggle.rollout / 100));
    expect(Math.abs(enabledCount - expectedCount)).toBeLessThan(5);
  }
}
```

## Why This Is Asked
Tests that exercise keyboard accessibility demonstrate familiarity with a11y concepts and deterministic testing approaches for beginners.

## Key Concepts
- Keyboard navigation and focus management
- ARIA roles and attributes (role=dialog, aria-label, aria-live)
- Test determinism with seeded localStorage and deterministic delays

## Code Example

```javascript
// Example test outline in Cypress
describe('Keyboard accessibility for notes', () => {
  it('navigates via Tab, opens modal, saves, edits, deletes, and persists', () => {
    // seed
    window.localStorage.setItem('notes', JSON.stringify([
      { id: 1, title: 'Note 1', body: 'Body 1' },
      { id: 2, title: 'Note 2', body: 'Body 2' }
    ]));

    cy.visit('/');

    // Tab through list and verify focus
    cy.get('[data-testid="note-item"]').first().focus();
    cy.focused().should('have.attr', 'role', 'listitem');

    // Open create modal with keyboard
    cy.get('[data-testid="create-button"]').focus().type('{enter}');
    cy.get('[role="dialog"]').should('be.visible');

    // Create note
    cy.get('[data-testid="note-title"]').type('New Note');
    cy.get('[data-testid="note-body"]').type('New Body');
    cy.get('[data-testid="save-button"]').click();

    // Edit existing note
    cy.get('[data-testid="note-item"]').first().focus().type('{enter}');
    cy.get('[data-testid="note-title"]').clear().type('Edited Title');
    cy.get('[data-testid="save-button"]').click();

    // Delete note
    cy.get('[data-testid="note-item"]').first().focus();
    cy.get('[data-testid="delete-button"]').click();

    // Verify persistence after reload
    cy.reload();
    cy.window().then(win => {
      const notes = JSON.parse(win.localStorage.getItem('notes'));
      expect(notes).to.have.length(2);
    });
  });
});
```

## Why This Is Asked
This question evaluates the ability to design realistic cross-service end-to-end tests with real-time updates, failure modes, and proper data isolation.

## Key Concepts
- Real-time event streams (WebSocket/SSE) and state machine validation
- Test isolation with per-tenant data and fresh environments
- Deterministic inputs via seed data and mocked external services
- Idempotency and eventual consistency verification across services
- Failure injection testing (disconnects, latency, partial outages)

## Code Example
```javascript
// Pseudo-test sketch using Playwright
const { test, expect } = require('@playwright/test');

test.describe('E2E Food Delivery Flow', () => {
  let wsServer, testData;

  test.beforeAll(async () => {
    wsServer = await startMockWebSocketServer();
    testData = await seedDeterministicTestData();
  });

  test('complete delivery flow with driver tracking', async ({ page }) => {
    const driverUpdates = [];

    // Simulate real-time driver location stream
    wsServer.on('driver-location', (data) => driverUpdates.push(data));

    // 1. Place order
    await page.goto('/order');
    await page.fill('#address', testData.address);
    await page.click('#place-order');
    const orderId = await expectOrderConfirmed(page);

    // 2. Restaurant accepts
    await wsServer.emit('order-status', { orderId, status: 'accepted' });
    await expectOrderStatus(page, 'accepted');

    // 3. Driver assigned
    await wsServer.emit('driver-assigned', { orderId, driver: testData.driver });
    await expectDriverAssigned(page, testData.driver);

    // 4. Verify location/ETA streaming
    await wsServer.emit('driver-location', { lat: 40.7128, lng: -74.0060, eta: 10 });
    await expectETA(page, '10 min');

    // 5. Payment processed
    await stubPaymentAPI({ orderId, status: 'success' });
    await expectPaymentStatus(page, 'paid');

    // 6. Delivery completes
    await wsServer.emit('order-status', { orderId, status: 'delivered' });
    await expectOrderStatus(page, 'delivered');

    // Verify idempotent event handling
    await wsServer.emit('order-status', { orderId, status: 'delivered' });
    expect(driverUpdates).toHaveLength(1); // No duplicate processing

    // Verify eventual consistency
    await expectExternalServiceSynced(orderId);
  });

  test('handles driver disconnect gracefully', async ({ page }) => {
    const orderId = await placeOrder(page);
    await wsServer.simulateDisconnect();

    await expectReconnectionLogic(page);
    await expectDriverReassigned(page);
  });
});
```

## Why This Is Asked

Tests for feature flags coupled with onboarding flows ensure correct gating, deterministic environments, and resilience to network issues. It checks seeding, isolation, and cleanup in addition to UI correctness.

## Key Concepts

- Feature flags and API-driven toggles
- Test data seeding and environment isolation
- End-to-end UI assertions for multi-step flows
- Network fault simulation and idempotent retries
- Cleanup and restoration of test state

## Code Example

```javascript
// Playwright example sketch
const { test, expect } = require('@playwright/test');

test('new-onboarding flow gated by feature flag', async ({ request, page }) => {
  // enable flag for test user
  await request.post('/api/flags', { data: { userId: 'test-user', flag: 'new-onboarding', value: true } });
  // seed data and start session
  await request.post('/api/tests/seed', { data: { userId: 'test-user', env: 'e2e' } });
  await page.goto('/onboarding');
  // verify four steps render
  for (let i = 1; i <= 4; i++) {
    await expect(page.locator(`#step-${i}`)).toBeVisible();
    await page.click(`#step-${i}-next`);
  }
  // final dashboard
  await expect(page).toHaveURL('/dashboard');
});
```

